//! Cargo-driven `evr.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The body is evr-rust; reactos-link builds the PE.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_DllMainCRTStartup@12", None),
        "x86_64" => ("x86_64-pc-windows-gnu", "DllMainCRTStartup", None),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "DllMainCRTStartup", None),
        o => panic!("evr-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["dll/win32/evr/evr_classes_r.o", "body", "engine:wine", "engine:c:wine_dll_register", "engine:c:wine_dll_canunload", "engine:c:strmbase", "engine:c:mfuuid", "engine:c:strmiids", "engine:uuid", "engine:c:dxguid", "engine:oldnames", "import:mfplat", "import:ole32", "import:oleaut32", "import:user32", "import:d3d9", "import:dxva2", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:delayimp_rust"],
        "x86_64" => &["dll/win32/evr/evr_classes_r.o", "body", "engine:wine", "engine:c:wine_dll_register", "engine:c:wine_dll_canunload", "engine:c:strmbase", "engine:c:mfuuid", "engine:c:strmiids", "engine:uuid", "engine:c:dxguid", "engine:oldnames", "import:mfplat", "import:ole32", "import:oleaut32", "import:user32", "import:d3d9", "import:dxva2", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:delayimp_rust"],
        "aarch64" => &["dll/win32/evr/evr_classes_r.o", "body", "engine:wine", "engine:c:wine_dll_register", "engine:c:wine_dll_canunload", "engine:c:strmbase", "engine:c:mfuuid", "engine:c:strmiids", "engine:uuid", "engine:c:dxguid", "engine:oldnames", "import:mfplat", "import:ole32", "import:oleaut32", "import:user32", "import:d3d9", "import:dxva2", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:delayimp_rust"],
        _ => unreachable!(),
    };

    // cmake built the body with these RUSTFLAGS (its rust_staticlib_variant ENV).
    let body_rustflags = match arch.as_str() {
        "x86" => Some("-C target-feature=+sse,+sse2"),
        _ => None,
    };
    let mut link = Linker::new(target_json);
    if let Some(flags) = body_rustflags {
        link = link.rust_build_rustflags(flags);
    }
    link
        .rust_staticlib("evr-rust")
        .spec2def("dll/win32/evr/evr.spec", "evr.dll")
        .spec_stubs()
        .delay_import_lib("dll/win32/mfplat/mfplat.spec", "mfplat.dll", "mfplat")
        .import_lib("dll/win32/ole32/ole32.spec", "ole32.dll", "ole32")
        .import_lib("dll/win32/oleaut32/oleaut32.spec", "oleaut32.dll", "oleaut32")
        .import_lib("win32ss/user/user32/user32.spec", "user32.dll", "user32")
        .import_lib("dll/directx/wine/d3d9/d3d9.spec", "d3d9.dll", "d3d9")
        .import_lib("dll/directx/wine/dxva2/dxva2.spec", "dxva2.dll", "dxva2")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .msvcrtex_crt(MsvcrtexKind::Dll)
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
